BEGIN READ ONLY;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='anon' AND rolsuper=false AND rolinherit=true AND rolcanlogin=false AND rolcreatedb=false AND rolcreaterole=false AND rolreplication=false AND rolbypassrls=false AND rolconfig IS NOT DISTINCT FROM ARRAY['statement_timeout=3s']::text[]) THEN RAISE EXCEPTION 'provider role mismatch: anon'; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='authenticated' AND rolsuper=false AND rolinherit=true AND rolcanlogin=false AND rolcreatedb=false AND rolcreaterole=false AND rolreplication=false AND rolbypassrls=false AND rolconfig IS NOT DISTINCT FROM ARRAY['statement_timeout=8s']::text[]) THEN RAISE EXCEPTION 'provider role mismatch: authenticated'; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='postgres' AND rolsuper=false AND rolinherit=true AND rolcanlogin=true AND rolcreatedb=true AND rolcreaterole=true AND rolreplication=true AND rolbypassrls=true AND rolconfig IS NOT DISTINCT FROM ARRAY['search_path="\$user", public, extensions','statement_timeout=2min']::text[]) THEN RAISE EXCEPTION 'provider role mismatch: postgres'; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='service_role' AND rolsuper=false AND rolinherit=true AND rolcanlogin=false AND rolcreatedb=false AND rolcreaterole=false AND rolreplication=false AND rolbypassrls=true AND rolconfig IS NOT DISTINCT FROM ARRAY['statement_timeout=8s']::text[]) THEN RAISE EXCEPTION 'provider role mismatch: service_role'; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='supabase_auth_admin' AND rolsuper=false AND rolinherit=false AND rolcanlogin=true AND rolcreatedb=false AND rolcreaterole=true AND rolreplication=false AND rolbypassrls=false AND rolconfig IS NOT DISTINCT FROM ARRAY['search_path=auth','idle_in_transaction_session_timeout=60000','log_statement=none']::text[]) THEN RAISE EXCEPTION 'provider role mismatch: supabase_auth_admin'; END IF; END $$;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_auth_members WHERE member IN('anon'::regrole,'authenticated'::regrole,'service_role'::regrole,'supabase_auth_admin'::regrole)) THEN RAISE EXCEPTION 'unexpected SQL test-role inherited membership'; END IF; IF (SELECT count(*) FROM pg_auth_members WHERE member='postgres'::regrole AND roleid IN('anon'::regrole,'authenticated'::regrole,'service_role'::regrole) AND admin_option AND inherit_option AND set_option)<>3 THEN RAISE EXCEPTION 'SQL SET ROLE membership mismatch'; END IF; END $$;
COMMIT;
